    #[invariant(i <= n)]
    #[invariant(forall(|j: usize| j < i ==> a[j] == 1))]
    #[invariant(forall(|j: usize| j < i ==> b[j] == 1))]
    #[decreases(n - i)]
    for i in 0..n {
        a[i] = 1;
        b[i] = 1;
    }

    // Initialize the single accumulator entry to 0
